@extends('layouts.app') @section('title','Detalle de venta') @section('content')<div class="flex flex-wrap justify-between gap-4"><div><h1>{{ $sale->document?->number??'Venta #'.$sale->id }}</h1><p class="mt-2 text-sm text-slate-500">{{ $sale->customer->name }} · {{ $sale->created_at->format('d/m/Y H:i') }} · {{ $sale->user->name }}</p></div><div class="flex items-start gap-3"><span class="badge">{{ $sale->status==='cancelled'?'Anulada':'Confirmada' }}</span>@if($sale->document&&Route::has('documents.show')) @can('documents.view')<a class="btn-secondary" href="{{ route('documents.show',$sale->document) }}">Ver comprobante</a><a class="btn" href="{{ route('documents.pdf',$sale->document) }}">Descargar PDF</a>@endcan @endif</div></div>@if($sale->status==='cancelled')<div class="rounded-xl bg-red-50 p-5 text-sm text-red-700">Venta anulada: {{ $sale->cancellation_reason }}. Los pagos se conservan como histórico; verifica el reembolso por separado.</div>@endif<div class="card overflow-hidden"><div class="overflow-x-auto"><table class="w-full"><thead><tr><th>Producto</th><th>Cantidad</th><th>Precio</th><th>Descuento</th><th>Impuestos</th><th>Total</th></tr></thead><tbody>@foreach($sale->items as $item)<tr><td>{{ $item->description }}</td><td>{{ $item->quantity }}</td><td>${{ $item->unit_price }}</td><td>${{ $item->discount }}</td><td>${{ $item->tax }}</td><td>${{ $item->total }}</td></tr>@endforeach</tbody></table></div><div class="space-y-2 p-6 text-right"><p>Subtotal: ${{ $sale->subtotal }}</p><p>Descuentos: ${{ $sale->discount }}</p><p>Impuestos: ${{ $sale->tax }}</p><p class="text-xl font-bold">Total: ${{ $sale->total }}</p>@foreach($sale->payments as $payment)<p class="text-sm text-slate-500">{{ ['cash'=>'Efectivo','transfer'=>'Transferencia','card'=>'Tarjeta'][$payment->method] }} · Recibido: ${{ $payment->tendered }} · Cambio: ${{ $payment->change }}</p>@endforeach</div></div>@if(auth()->user()->role?->name==='Administrador'&&$sale->status==='completed')<form class="card max-w-2xl space-y-4 p-6" method="POST" action="{{ route('sales.cancel',$sale) }}" onsubmit="return confirm('¿Anular la venta y restituir su inventario? Debes gestionar el reembolso por separado.')">@csrf<h2>Anulación controlada</h2><label>Motivo obligatorio<input name="reason" required minlength="5" maxlength="255"></label><button class="btn bg-red-600 hover:bg-red-700">Anular y revertir inventario</button></form>@endif @endsection
